    return None

def mean_std(arr):
    if not arr:
        return 0.0, 0.0
    m = sum(arr) / len(arr)
    var = sum((x - m) ** 2 for x in arr) / len(arr)
    return m, math.sqrt(var)

def median(arr):
    if not arr:
        return 0.0
    s = sorted(arr)
    n = len(s)
    if n % 2 == 1:
